using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using Racer;using Object=UnityEngine.Object;
public static class DrainBendClearance {public static string Main(){EditorSceneManager.OpenScene("Assets/Scenes/DansBackyardReverse.unity");var b=Object.FindObjectsByType<WoodlandRoute>().Single(x=>x.title.StartsWith("Storm"));var mf=GameObject.Find("Long storm culvert walls and ceiling").GetComponent<MeshFilter>();var m=Object.Instantiate(mf.sharedMesh);var v=m.vertices;for(int i=0;i<v.Length;i++){float s=b.Project(v[i],out _);var p=b.At(s,out var f);var side=Vector3.Cross(Vector3.up,f).normalized;float d=Vector3.Dot(v[i]-p,side);float extra=.85f*(1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(55,80,s)));v[i]+=side*Mathf.Sign(d)*extra;}m.vertices=v;m.RecalculateNormals();m.RecalculateBounds();AssetDatabase.CreateAsset(m,"Assets/Track/SevenCorrections/Drain entrance bend clearance.asset");mf.sharedMesh=m;mf.GetComponent<MeshCollider>().sharedMesh=m;
 foreach(var t in Object.FindObjectsByType<Transform>().Where(t=>t.name=="Supported culvert mouth pier")){float s=b.Project(t.position,out _);if(s>30)continue;var p=b.At(b.undergroundStart,out var f);var side=Vector3.Cross(Vector3.up,f).normalized;t.position+=side*Mathf.Sign(Vector3.Dot(t.position-p,side))*.85f;}foreach(var t in Object.FindObjectsByType<Transform>().Where(t=>t.name=="Culvert mouth lintel"&&b.Project(t.position,out _)<30))t.localScale+=Vector3.right*1.7f;
 int removed=0;foreach(var ground in Object.FindObjectsByType<MeshFilter>().Where(x=>x.name.StartsWith("Ground_")&&x.name!="Ground_Culvert seamless floor"&&x.GetComponent<MeshCollider>()&&x.GetComponent<Renderer>().bounds.Intersects(new Bounds(new(159,58,63),new(50,40,58))))){var src=ground.sharedMesh;v=src.vertices;var t=src.triangles;var keep=new List<int>();int count=0;for(int i=0;i<t.Length;i+=3){var p=ground.transform.TransformPoint((v[t[i]]+v[t[i+1]]+v[t[i+2]])/3);float s=b.Project(p,out float d);float y=b.At(s,out _).y;if(p.x>138&&p.x<180&&p.z>35&&p.z<85&&s>.2f&&s<70&&d<4.4f&&p.y>y-4&&p.y<y+5.3f){count++;continue;}keep.AddRange(new[]{t[i],t[i+1],t[i+2]});}if(count==0)continue;m=Object.Instantiate(src);m.triangles=keep.ToArray();m.RecalculateBounds();AssetDatabase.CreateAsset(m,AssetDatabase.GenerateUniqueAssetPath("Assets/Track/SevenCorrections/Drain bend terrain clearance.asset"));ground.sharedMesh=m;ground.GetComponent<MeshCollider>().sharedMesh=m;removed+=count;}
 EditorSceneManager.MarkSceneDirty(mf.gameObject.scene);EditorSceneManager.SaveScene(mf.gameObject.scene);AssetDatabase.SaveAssets();File.WriteAllText("Docs/SevenCorrections/entry-bend-clearance.txt","Additional 0.85m each side only through entrance bends, tapers at stations 55-80 to the 6.7m dark inner chamber. Removed matching intersecting terrain faces="+removed);return "Entry bend clearance corrected";}}
